class Solution {
  private int[] parent;

  private int find(int x) {
    while (parent[x] != x) {
      parent[x] = parent[parent[x]];
      x = parent[x];
    }
    return x;
  }

  public int countComponents(int[] nums, int threshold) {
    parent = new int[threshold + 1];
    for (int i = 0; i <= threshold; i++) parent[i] = i;
    int isolated = 0;
    for (int a : nums) {
      if (a > threshold) {
        isolated++;
        continue;
      }
      int ra = find(a);
      for (int m = 2 * a; m <= threshold; m += a) {
        int rm = find(m);
        if (rm != ra) parent[rm] = ra;
      }
    }
    java.util.HashSet<Integer> roots = new java.util.HashSet<>();
    for (int a : nums) if (a <= threshold) roots.add(find(a));
    return isolated + roots.size();
  }
}
